     1→// 🦎 Mini Zig Compiler - Phase 2.4: Sema
     2→// src/sema.zig: Semantic Analysis (Type Checking & Symbol Resolution)
     3→
     4→const std = @import("std");
     5→const Zir = @import("zir.zig").Zir;
     6→const Air = @import("air.zig").Air;
     7→const AirType = @import("air.zig").Type;
     8→const Location = @import("tokenizer.zig").Location;
     9→
    10→/// Semantic Error Types
    11→pub const SemanticError = union(enum) {
    12→    undefined_variable: struct {
    13→        name: []const u8,
    14→        location: Location,
    15→    },
    16→    duplicate_declaration: struct {
    17→        name: []const u8,
    18→        location: Location,
    19→    },
    20→    type_mismatch: struct {
    21→        expected: AirType,
    22→        got: AirType,
    23→        location: Location,
    24→    },
    25→    wrong_arg_count: struct {
    26→        function: []const u8,
    27→        expected: usize,
    28→        got: usize,
    29→        location: Location,
    30→    },
    31→    const_reassignment: struct {
    32→        name: []const u8,
    33→        location: Location,
    34→    },
    35→    non_bool_condition: struct {
    36→        got: AirType,
    37→        location: Location,
    38→    },
    39→    non_function_call: struct {
    40→        got: AirType,
    41→        location: Location,
    42→    },
    43→    invalid_binary_op: struct {
    44→        op: []const u8,
    45→        lhs_ty: AirType,
    46→        rhs_ty: AirType,
    47→        location: Location,
    48→    },
    49→    invalid_unary_op: struct {
    50→        op: []const u8,
    51→        operand_ty: AirType,
    52→        location: Location,
    53→    },
    54→};
    55→
    56→/// Symbol Information
    57→pub const Symbol = struct {
    58→    name: []const u8,
    59→    ty: AirType,
    60→    is_mutable: bool,
    61→    location: Location,
    62→};
    63→
    64→/// Symbol Table (with Scope Support)
    65→pub const SymbolTable = struct {
    66→    symbols: std.StringHashMap(Symbol),
    67→    parent_scope: ?*SymbolTable,
    68→    allocator: std.mem.Allocator,
    69→
    70→    pub fn init(allocator: std.mem.Allocator, parent_scope: ?*SymbolTable) SymbolTable {
    71→        return .{
    72→            .symbols = std.StringHashMap(Symbol).init(allocator),
    73→            .parent_scope = parent_scope,
    74→            .allocator = allocator,
    75→        };
    76→    }
    77→
    78→    pub fn deinit(self: *SymbolTable) void {
    79→        self.symbols.deinit();
    80→    }
    81→
    82→    /// 변수 선언
    83→    pub fn declare(
    84→        self: *SymbolTable,
    85→        name: []const u8,
    86→        ty: AirType,
    87→        is_mutable: bool,
    88→        location: Location,
    89→    ) !void {
    90→        if (self.symbols.contains(name)) {
    91→            return error.DuplicateDeclaration;
    92→        }
    93→        try self.symbols.put(name, .{
    94→            .name = name,
    95→            .ty = ty,
    96→            .is_mutable = is_mutable,
    97→            .location = location,
    98→        });
    99→    }
   100→
   101→    /// 변수 조회 (현재 스코프 및 부모 스코프)
   102→    pub fn lookup(self: *SymbolTable, name: []const u8) ?Symbol {
   103→        if (self.symbols.get(name)) |symbol| {
   104→            return symbol;
   105→        }
   106→
   107→        if (self.parent_scope) |parent| {
   108→            return parent.lookup(name);
   109→        }
   110→
   111→        return null;
   112→    }
   113→
   114→    /// 현재 스코프에서만 조회
   115→    pub fn lookupLocal(self: *SymbolTable, name: []const u8) ?Symbol {
   116→        return self.symbols.get(name);
   117→    }
   118→};
   119→
   120→/// Type Inference Engine
   121→pub const TypeInference = struct {
   122→    allocator: std.mem.Allocator,
   123→    symbol_table: *SymbolTable,
   124→
   125→    pub fn init(allocator: std.mem.Allocator, symbol_table: *SymbolTable) TypeInference {
   126→        return .{
   127→            .allocator = allocator,
   128→            .symbol_table = symbol_table,
   129→        };
   130→    }
   131→
   132→    /// ZIR 명령어에서 타입 추론
   133→    pub fn inferType(self: *TypeInference, zir_inst: Zir.Instruction) !AirType {
   134→        return switch (zir_inst) {
   135→            .load_int => .i32, // 기본은 i32
   136→            .load_float => .f64, // 기본은 f64
   137→            .load_string => .string,
   138→            .load_var => |data| blk: {
   139→                // 심볼 테이블에서 변수 타입 조회
   140→                // 나중에 구현 (현재는 unknown 반환)
   141→                break :blk .unknown;
   142→            },
   143→            .binary_op => |data| try self.inferBinaryOpType(data.op),
   144→            .unary_op => |data| try self.inferUnaryOpType(data.op),
   145→            .call => .unknown, // 함수 호출 타입은 함수 정의에서 결정
   146→            else => .unknown,
   147→        };
   148→    }
   149→
   150→    /// 이항 연산 결과 타입 추론
   151→    fn inferBinaryOpType(self: *TypeInference, op: Zir.BinaryOp) !AirType {
   152→        _ = self;
   153→        return switch (op) {
   154→            // 산술 연산: i32, i64, f32, f64 → 같은 타입
   155→            .add, .sub, .mul, .div, .mod => .i32, // 기본은 i32
   156→            // 비교 연산: 모든 타입 → bool
   157→            .eq, .ne, .lt, .le, .gt, .ge => .bool,
   158→            // 논리 연산: bool → bool
   159→            .logical_and, .logical_or => .bool,
   160→            // 비트 연산: i32, i64 → 같은 타입
   161→            .bitwise_and, .bitwise_or, .bitwise_xor, .lshift, .rshift => .i32,
   162→        };
   163→    }
   164→
   165→    /// 단항 연산 결과 타입 추론
   166→    fn inferUnaryOpType(self: *TypeInference, op: Zir.UnaryOp) !AirType {
   167→        _ = self;
   168→        return switch (op) {
   169→            .negate => .i32, // -x: 숫자 → 숫자
   170→            .not => .bool, // !x: 불린 → 불린
   171→            .bitwise_not => .i32, // ~x: 정수 → 정수
   172→        };
   173→    }
   174→
   175→    /// 이항 연산 타입 검사
   176→    pub fn checkBinaryOp(self: *TypeInference, op: Zir.BinaryOp, lhs_ty: AirType, rhs_ty: AirType) !AirType {
   177→        _ = self;
   178→        // 산술 연산: 양쪽 모두 i32 또는 f64
   179→        switch (op) {
   180→            .add, .sub, .mul, .div, .mod => {
   181→                if (isNumericType(lhs_ty) and isNumericType(rhs_ty)) {
   182→                    return lhs_ty; // 좌측 타입으로 통일
   183→                }
   184→                return error.TypeMismatch;
   185→            },
   186→            // 비교 연산: 양쪽 타입이 같음
   187→            .eq, .ne, .lt, .le, .gt, .ge => {
   188→                if (Air.typeEq(lhs_ty, rhs_ty)) {
   189→                    return .bool;
   190→                }
   191→                return error.TypeMismatch;
   192→            },
   193→            // 논리 연산: 양쪽 모두 bool
   194→            .logical_and, .logical_or => {
   195→                if (lhs_ty == .bool and rhs_ty == .bool) {
   196→                    return .bool;
   197→                }
   198→                return error.TypeMismatch;
   199→            },
   200→            // 비트 연산: 양쪽 모두 i32 또는 i64
   201→            .bitwise_and, .bitwise_or, .bitwise_xor, .lshift, .rshift => {
   202→                if (isIntegerType(lhs_ty) and isIntegerType(rhs_ty)) {
   203→                    return lhs_ty;
   204→                }
   205→                return error.TypeMismatch;
   206→            },
   207→        }
   208→    }
   209→
   210→    /// 단항 연산 타입 검사
   211→    pub fn checkUnaryOp(self: *TypeInference, op: Zir.UnaryOp, operand_ty: AirType) !AirType {
   212→        _ = self;
   213→        return switch (op) {
   214→            .negate => blk: {
   215→                if (isNumericType(operand_ty)) {
   216→                    break :blk operand_ty;
   217→                }
   218→                return error.TypeMismatch;
   219→            },
   220→            .not => blk: {
   221→                if (operand_ty == .bool) {
   222→                    break :blk .bool;
   223→                }
   224→                return error.TypeMismatch;
   225→            },
   226→            .bitwise_not => blk: {
   227→                if (isIntegerType(operand_ty)) {
   228→                    break :blk operand_ty;
   229→                }
   230→                return error.TypeMismatch;
   231→            },
   232→        };
   233→    }
   234→};
   235→
   236→/// 숫자 타입 확인
   237→fn isNumericType(ty: AirType) bool {
   238→    return switch (ty) {
   239→        .i32, .i64, .f32, .f64 => true,
   240→        else => false,
   241→    };
   242→}
   243→
   244→/// 정수 타입 확인
   245→fn isIntegerType(ty: AirType) bool {
   246→    return switch (ty) {
   247→        .i32, .i64 => true,
   248→        else => false,
   249→    };
   250→}
   251→
   252→/// Semantic Analyzer (메인 분석기)
   253→pub const Sema = struct {
   254→    zir: *const Zir,
   255→    air: *Air,
   256→    allocator: std.mem.Allocator,
   257→
   258→    symbol_table: SymbolTable,
   259→    type_infer: TypeInference,
   260→
   261→    errors: std.ArrayList(SemanticError),
   262→    current_function: ?[]const u8 = null,
   263→    function_return_type: ?AirType = null,
   264→
   265→    pub fn init(allocator: std.mem.Allocator, zir: *const Zir) !Sema {
   266→        var air = try allocator.create(Air);
   267→        air.* = Air.init(allocator);
   268→
   269→        var symbol_table = SymbolTable.init(allocator, null);
   270→
   271→        return .{
   272→            .zir = zir,
   273→            .air = air,
   274→            .allocator = allocator,
   275→            .symbol_table = symbol_table,
   276→            .type_infer = TypeInference.init(allocator, &symbol_table),
   277→            .errors = std.ArrayList(SemanticError).init(allocator),
   278→        };
   279→    }
   280→
   281→    pub fn deinit(self: *Sema) void {
   282→        self.symbol_table.deinit();
   283→        self.air.deinit();
   284→        self.allocator.destroy(self.air);
   285→        self.errors.deinit();
   286→    }
   287→
   288→    /// 전체 ZIR 분석
   289→    pub fn analyzeProgram(self: *Sema) !void {
   290→        // 1단계: 모든 선언 수집 (forward pass)
   291→        // 2단계: 타입 검사 및 AIR 생성 (analysis pass)
   292→
   293→        // 현재 간단한 구현: 순차적으로 처리
   294→        for (self.zir.instructions.items, 0..) |zir_inst, idx| {
   295→            _ = self.analyzeInstruction(zir_inst, idx) catch |err| {
   296→                // 에러 계속 수집
   297→                continue;
   298→            };
   299→        }
   300→    }
   301→
   302→    /// 개별 명령어 분석
   303→    fn analyzeInstruction(self: *Sema, zir_inst: Zir.Instruction, idx: usize) !void {
   304→        _ = idx;
   305→
   306→        switch (zir_inst) {
   307→            .load_int => |data| {
   308→                _ = try self.air.addInstruction(.{
   309→                    .load_int = .{
   310→                        .value = data.value,
   311→                        .ty = .i32,
   312→                    },
   313→                });
   314→            },
   315→            .load_float => |data| {
   316→                _ = try self.air.addInstruction(.{
   317→                    .load_float = .{
   318→                        .value = data.value,
   319→                        .ty = .f64,
   320→                    },
   321→                });
   322→            },
   323→            .load_string => |data| {
   324→                _ = try self.air.addInstruction(.{
   325→                    .load_string = .{
   326→                        .index = data.index,
   327→                        .ty = .string,
   328→                    },
   329→                });
   330→            },
   331→            .load_var => |data| {
   332→                _ = try self.air.addInstruction(.{
   333→                    .load_var = .{
   334→                        .name_index = data.name_index,
   335→                        .ty = .unknown,
   336→                    },
   337→                });
   338→            },
   339→            .store_var => |data| {
   340→                _ = try self.air.addInstruction(.{
   341→                    .store_var = .{
   342→                        .name_index = data.name_index,
   343→                        .value = data.value,
   344→                        .ty = .unknown,
   345→                    },
   346→                });
   347→            },
   348→            .binary_op => |data| {
   349→                // 타입 검사 수행
   350→                const result_ty = try self.type_infer.inferBinaryOpType(data.op);
   351→                _ = try self.air.addInstruction(.{
   352→                    .binary_op = .{
   353→                        .op = data.op,
   354→                        .lhs = data.lhs,
   355→                        .rhs = data.rhs,
   356→                        .result_ty = result_ty,
   357→                    },
   358→                });
   359→            },
   360→            .unary_op => |data| {
   361→                const result_ty = try self.type_infer.inferUnaryOpType(data.op);
   362→                _ = try self.air.addInstruction(.{
   363→                    .unary_op = .{
   364→                        .op = data.op,
   365→                        .operand = data.operand,
   366→                        .result_ty = result_ty,
   367→                    },
   368→                });
   369→            },
   370→            .fn_begin => |data| {
   371→                _ = try self.air.addInstruction(.{
   372→                    .fn_begin = .{
   373→                        .name_index = data.name_index,
   374→                        .params = data.params,
   375→                        .return_ty = .void, // 기본 반환 타입
   376→                    },
   377→                });
   378→            },
   379→            .fn_end => {
   380→                _ = try self.air.addInstruction(.fn_end);
   381→            },
   382→            .call => |data| {
   383→                _ = try self.air.addInstruction(.{
   384→                    .call = .{
   385→                        .callee = data.callee,
   386→                        .args = data.args,
   387→                        .return_ty = .unknown,
   388→                    },
   389→                });
   390→            },
   391→            .return_val => |ret| {
   392→                _ = try self.air.addInstruction(.{ .return_val = ret });
   393→            },
   394→            .cond_br => |data| {
   395→                _ = try self.air.addInstruction(.{
   396→                    .cond_br = .{
   397→                        .cond = data.cond,
   398→                        .then_block = data.then_block,
   399→                        .else_block = data.else_block,
   400→                    },
   401→                });
   402→            },
   403→            .block_begin => |data| {
   404→                _ = try self.air.addInstruction(.{
   405→                    .block_begin = .{ .label = data.label },
   406→                });
   407→            },
   408→            .block_end => {
   409→                _ = try self.air.addInstruction(.block_end);
   410→            },
   411→            .array_literal => |data| {
   412→                _ = try self.air.addInstruction(.{
   413→                    .array_literal = .{
   414→                        .elements = data.elements,
   415→                        .element_ty = .unknown,
   416→                    },
   417→                });
   418→            },
   419→            .loop_begin => |data| {
   420→                _ = try self.air.addInstruction(.{
   421→                    .loop_begin = .{ .label = data.label },
   422→                });
   423→            },
   424→            .loop_end => {
   425→                _ = try self.air.addInstruction(.loop_end);
   426→            },
   427→            else => {
   428→                // 기타 명령어는 그대로 복사
   429→                _ = try self.air.addInstruction(zir_inst);
   430→            },
   431→        }
   432→    }
   433→
   434→    /// 에러 보고
   435→    pub fn reportError(self: *Sema, err: SemanticError) !void {
   436→        try self.errors.append(err);
   437→    }
   438→
   439→    /// 에러 확인
   440→    pub fn hasErrors(self: *Sema) bool {
   441→        return self.errors.items.len > 0;
   442→    }
   443→
   444→    /// 에러 개수
   445→    pub fn errorCount(self: *Sema) usize {
   446→        return self.errors.items.len;
   447→    }
   448→
   449→    /// 에러 출력
