   470→                    stdout.print("Error: type mismatch\n  expected: {s}\n  got: {s}\n  at line {}, column {}\n\n", .{
   471→                        Air.typeName(data.expected),
   472→                        Air.typeName(data.got),
   473→                        data.location.line,
   474→                        data.location.column,
   475→                    }) catch {};
   476→                },
   477→                .wrong_arg_count => |data| {
   478→                    stdout.print("Error: function '{s}' expects {} arguments, got {}\n  at line {}, column {}\n\n", .{
   479→                        data.function,
   480→                        data.expected,
   481→                        data.got,
