            0 => "+",    // add
            1 => "-",    // sub
            2 => "*",    // mul
            3 => "/",    // div
            4 => "%",    // mod
            5 => "==",   // eq
            6 => "!=",   // ne
            7 => "<",    // lt
            8 => "<=",   // le
            9 => ">",    // gt
            10 => ">=",  // ge
            11 => "&&",  // and
            12 => "||",  // or
            13 => "^",   // xor
            14 => "<<",  // lshift
            15 => ">>",  // rshift
            else => "+",
        };
